package com.volvocars.ecom.customerservice.api.customer.v1.impl;

import com.volvocars.ecom.customerservice.api.customer.v1.MigrationController;
import com.volvocars.ecom.customerservice.api.customer.v1.mapper.CustomerResponseMapper;
import com.volvocars.ecom.customerservice.customer.Customer;
import com.volvocars.ecom.customerservice.customer.CustomerResponse;
import com.volvocars.ecom.customerservice.migrate.MigrateCustomerRequest;
import com.volvocars.ecom.customerservice.migrate.MigrationService;
import com.volvocars.ecom.web.common.ControllerBase;
import com.volvocars.services.web.model.BaseResponse;
import com.volvocars.services.web.model.SuccessResponse;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/v1/migrate")
public class MigrationControllerImpl extends ControllerBase implements MigrationController {
  private final CustomerResponseMapper customerResponseMapper;
  private final MigrationService migrationService;

  public MigrationControllerImpl(
      CustomerResponseMapper customerResponseMapper, MigrationService migrationService) {
    this.customerResponseMapper = customerResponseMapper;
    this.migrationService = migrationService;
  }

  @Override
  public BaseResponse<CustomerResponse> migrateCustomer(
      MigrateCustomerRequest migrateCustomerRequest, boolean sendUpdateEvents) {
    Customer customer = migrationService.migrateCustomer(migrateCustomerRequest, sendUpdateEvents);
    return SuccessResponse.ok(customerResponseMapper.to(customer), this.getOperationId());
  }

  @Override
  public BaseResponse<Void> deleteCustomer(String customerId) {
    migrationService.deleteCustomer(customerId);
    return SuccessResponse.noContent();
  }
}

